#include "analysis.h"
#include <QDir>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QMap>
#include <QSet>
#include <cmath>
#include <algorithm>
namespace ga {
namespace {
QJsonObject read(const QString &path){QFile f(path);if(!f.open(QIODevice::ReadOnly)||f.size()>20*1024*1024)return{};return QJsonDocument::fromJson(f.readAll()).object();}
}
double distanceKm(double a,double b,double c,double d){const double rad=M_PI/180,dl=(c-a)*rad,dn=(d-b)*rad,h=std::pow(std::sin(dl/2),2)+std::cos(a*rad)*std::cos(c*rad)*std::pow(std::sin(dn/2),2);return 6371.0088*2*std::asin(std::sqrt(std::clamp(h,0.,1.)));}
QJsonObject nearestClimate(const QString &file,const Site &site){const auto root=read(file);QJsonObject nearest;double best=root["max_distance_km"].toDouble(100);for(const auto &v:root["stations"].toArray()){const auto station=v.toObject();if(!station["lat"].isDouble()||!station["lon"].isDouble())continue;const double d=distanceKm(site.lat,site.lon,station["lat"].toDouble(),station["lon"].toDouble());if(d<=best){best=d;nearest=station;nearest["distance_km"]=d;}}return nearest;}
QVector<QJsonObject> environmentFields(const QString &directory,const Site &site){QVector<QJsonObject> fields;QDir root(directory);for(const auto &name:root.entryList(QDir::Dirs|QDir::NoDotAndDotDot)){const auto base=root.filePath(name)+"/";const auto index=read(base+"index.json");for(const auto &v:index["entries"].toArray()){const auto entry=v.toObject();const auto bbox=entry["bbox"].toArray();if(bbox.size()!=4)continue;if(site.lon<bbox[0].toDouble()||site.lon>bbox[2].toDouble()||site.lat<bbox[1].toDouble()||site.lat>bbox[3].toDouble())continue;const auto field=read(base+QFileInfo(entry["file"].toString()).fileName());if(field["status"].toString()!="ready"||field["grid"].toArray().isEmpty())continue;fields.append(field);}}return fields;}
QColor rampColor(double t){t=std::clamp(t,0.,1.);const QVector<QColor> stops={QColor("#4d7774"),QColor("#b4c7ac"),QColor("#f0d59d"),QColor("#cf7157"),QColor("#8b3d45")};const double at=t*4;const int i=std::min(3,int(at));const double k=at-i;const auto a=stops[i],b=stops[i+1];return QColor::fromRgbF(a.redF()*(1-k)+b.redF()*k,a.greenF()*(1-k)+b.greenF()*k,a.blueF()*(1-k)+b.blueF()*k);}
QImage gridImage(const QJsonObject &field){const int w=field["width"].toInt(),h=field["height"].toInt();const auto rows=field["grid"].toArray();if(w<=0||h<=0||w>2048||h>2048||rows.size()!=h)return{};QImage image(w,h,QImage::Format_ARGB32);image.fill(Qt::transparent);const auto stats=field["statistics"].toObject();const double lo=stats["min"].toDouble(),hi=stats["max"].toDouble();if(!std::isfinite(lo)||!std::isfinite(hi)||hi<lo)return{};for(int y=0;y<h;++y){const auto row=rows[y].toArray();if(row.size()!=w)return{};for(int x=0;x<w;++x)if(row[x].isDouble()&&std::isfinite(row[x].toDouble()))image.setPixelColor(x,y,rampColor(hi>lo?(row[x].toDouble()-lo)/(hi-lo):.5));}return image;}
QJsonObject buildingAnalysis(const Project &p){QMap<QString,double> heights;QMap<QString,QString> sources,uses;QJsonArray bins{0,0,0,0,0,0};for(const auto &f:p.features)if(f.building()){const auto id=f.sourceId.isEmpty()?stableSourceId(f.id):f.sourceId;uses[id]=f.tags["building"].toString("unknown");if(f.knownHeight()){heights[id]=f.height;sources[id]=f.heightSource;}}for(const auto h:heights){const int i=h<5?0:h<10?1:h<20?2:h<40?3:h<80?4:5;bins[i]=bins[i].toInt()+1;}QMap<QString,int> useCount,sourceCount;for(const auto &v:uses)++useCount[v];for(const auto &v:sources)++sourceCount[v];QJsonObject useJson,sourceJson;for(auto i=useCount.begin();i!=useCount.end();++i)useJson[i.key()]=i.value();for(auto i=sourceCount.begin();i!=sourceCount.end();++i)sourceJson[i.key()]=i.value();return{{"height_bins",bins},{"height_sources",sourceJson},{"building_use",useJson},{"unknown_heights",uses.size()-heights.size()},{"footprint_note","Sum of clipped footprints, not polygon union or statutory coverage."}};}
QJsonObject dataQuality(const Project &p){QMap<QString,const Feature*> buildings;QMap<QString,QSet<QString>> records;for(const auto &f:p.features){const auto id=f.sourceId.isEmpty()?stableSourceId(f.id):f.sourceId;if(f.building()&&(!buildings.contains(id)||f.knownHeight()))buildings[id]=&f;for(const auto &v:f.provenance){const auto record=v.toObject();const auto dataset=record["dataset"].toString();if(!dataset.isEmpty())records[dataset].insert(record["record_id"].toVariant().toString().isEmpty()?id:record["record_id"].toVariant().toString());}}QMap<QString,int> heights{{"recorded",0},{"ai_estimate",0},{"floor_estimate",0},{"other_estimate",0},{"unknown_flat",0}};for(const auto f:buildings){const auto type=f->heightSource.toLower();if(!f->knownHeight())++heights["unknown_flat"];else if(type.contains("google_ai"))++heights["ai_estimate"];else if(type.contains("floor")||type.contains("level"))++heights["floor_estimate"];else if(type.contains("estimate"))++heights["other_estimate"];else ++heights["recorded"];}QJsonObject heightJson,recordJson;for(auto i=heights.begin();i!=heights.end();++i)heightJson[i.key()]=i.value();for(auto i=records.begin();i!=records.end();++i)recordJson[i.key()]=i.value().size();return{{"unique_buildings",buildings.size()},{"height_groups",heightJson},{"geometry_provenance_records",recordJson},{"source_window_fraction",p.source["coverage_fraction"]},{"completeness_note","These counts describe retained records, not real-world data completeness or surveyed accuracy."}};}
}
